const input = $input.first().json;
const message = String(input.message || '');

const URL_RE = /https?:\/\/[^\s<>"']+/gi;
const found = message.match(URL_RE) || [];

const urls = found
  .map((url) => url.replace(/[.,;:)\]]+$/, ''))
  .filter((url) => url.length > 12);

const ALLOWED = /(?:beaumont-?tiles|nationaltiles|bunnings|tilerepublic|tileimporter|ambertiles|tilecloud)\./i;

const tileUrl = urls.find((url) => ALLOWED.test(url)) || null;
const anyUrl = tileUrl || urls[0] || null;

let tileUrlDomain = null;
if (anyUrl) {
  try {
    tileUrlDomain = new URL(anyUrl).hostname.replace(/^www\./, '');
  } catch (error) {
    tileUrlDomain = null;
  }
}

return [{
  json: {
    ...input,
    tileUrl,
    hasTileUrl: Boolean(tileUrl),
    tileUrlDomain,
    unknownUrl: null,
  },
}];

