// The same conversions the lookup tool applies, because a price read off a page needs them
// just as much as one found by search. A tile the page priced per box is not priced per square
// metre, and the gap is large enough to put a whole quote out.
const source = $('Detect Tile URL').first().json;
const response = $input.first().json || {};

let product = {};
try {
  const raw = response.choices?.[0]?.message?.content || '';
  product = JSON.parse(String(raw).replace(/```json|```/g, '').trim()) || {};
} catch (error) {
  product = {};
}

const num = (value) => {
  const parsed = Number(String(value == null ? '' : value).replace(/[^0-9.]/g, ''));
  return Number.isFinite(parsed) && parsed > 0 ? parsed : null;
};

const price = num(product.price);
const unit = String(product.priceUnit || 'sqm').toLowerCase();
let pricePerSqm = null;
if (price !== null) {
  if (unit === 'sqm') pricePerSqm = price;
  else if (unit === 'box') {
    const coverage = num(product.boxCoverageSqm);
    // A box with no stated coverage cannot be converted. Guessing a coverage is how a quote
    // ends up 40% wrong with nothing on screen to explain it.
    if (coverage !== null) pricePerSqm = Math.round((price / coverage) * 100) / 100;
  }
}

// Australian retail tile sits roughly $15-250/m². Outside that, something was misread.
const valid = pricePerSqm !== null && pricePerSqm >= 15 && pricePerSqm <= 250 && product.name;

// The retailer's own domain, kept regardless of whether the page read succeeded. When it did
// not — a homepage or category page rather than one product — this is what lets the customer's
// search stay on the site they actually pasted, instead of forcing them to go find the exact
// product page themselves.
const tileUrlDomain = (() => {
  if (!source.tileUrl) return null;
  try {
    return new URL(source.tileUrl).hostname.replace(/^www\./, '');
  } catch (error) {
    return null;
  }
})();

return [{
  json: {
    ...source,
    tileFacts: valid
      ? {
          tileName: String(product.name).trim().slice(0, 120),
          tilePricePerSqm: pricePerSqm,
          tileRetailer: String(product.retailer || '').trim(),
          tileSourceUrl: source.tileUrl,
          tileConfidence: 'extracted',
        }
      : {},
    // The customer pasted a link expecting it to be read. Silence when it fails is worse than
    // saying so, so the agent is told and can mention it in one line.
    tileReadFailed: !valid,
    // Only kept on the failure path — once the page read has already produced a real product
    // and price, there is nothing left for a site-restricted search to add.
    tileUrlDomain: !valid ? tileUrlDomain : null,
  },
}];

// Two paths reach this node: a link was read (tileFacts present), or there was no link at all.
// From here on they are the same item, which keeps everything downstream single-shaped.
const item = $input.first().json;

// Documents describe a tiling job in trade shorthand — "25m2 of floor tiling", "600x600
// porcelain", "waterproof and tile shower recess". Read here rather than trusted to the model,
// for the same reason the fencing workflow reads fence documents in code: the same PDF must
// give the same fields on every run.
const text = String(item.extractedText || '').slice(0, 4000);

const num = (value) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : null;
};

const facts = { ...(item.tileFacts || {}) };

// The job address, for the picker's benefit only. This is NOT checklist.suburb and never
// becomes it — the agent's own prompt already says the same thing ("never take it from a
// document as fact"). It only ever gives the picker a head start; Google's confirmation is
// still what fills checklist.suburb. Labelled lines first, since a tiler's letterhead is also
// an address and quoting it would send the job to the wrong side of the city.
const ADDRESS = [
  /^[^\n]{0,40}\b(?:property|site|job|install(?:ation)?)\s*address\s*[:\-–]\s*([^\n]+)$/im,
  /^[^\n]{0,10}\baddress\s*[:\-–]\s*([^\n]+)$/im,
  /^[^\n]{0,40}\b(?:suburb|location)\s*[:\-–]\s*([^\n]+)$/im,
  // Unlabelled last resort: a place written the way Australian addresses are written.
  /\b([A-Z][A-Za-z'’\-]+(?:\s+[A-Z][A-Za-z'’\-]+){0,3}\s+(?:VIC|NSW|QLD|SA|WA|TAS|NT|ACT)\s+\d{4})\b/,
];

// The contractor's own address is on the page too, usually at the top, and suggesting it would
// send the job to whichever suburb the tiler trades from. A labelled line says whose address it
// is; an unlabelled one does not, so that line has to be clean of letterhead first.
const LETTERHEAD = /\b(?:abn|acn|pty|ltd|p\/l|phone|mobile|email|www\.|@|tiling|tiles?|constructions?|quotation|invoice|tax invoice)\b/i;

const readAddress = (source) => {
  for (let index = 0; index < ADDRESS.length; index += 1) {
    const match = source.match(ADDRESS[index]);
    if (!match) continue;
    const line = String(match[1] || '').trim().replace(/\s+/g, ' ').slice(0, 120);
    // A label with nothing useful after it ("Address: TBC") is not a location. A street number
    // or a state code is what makes it something Google can actually find.
    if (!line || !/\d|\b(?:VIC|NSW|QLD|SA|WA|TAS|NT|ACT)\b/i.test(line)) continue;
    // Only the last pattern is unlabelled, and only it needs the letterhead check — a line that
    // says "Property address" has already told us whose address it is.
    const unlabelled = index === ADDRESS.length - 1;
    if (unlabelled) {
      const lineStart = source.lastIndexOf('\n', match.index) + 1;
      let lineEnd = source.indexOf('\n', match.index);
      if (lineEnd === -1) lineEnd = source.length;
      if (LETTERHEAD.test(source.slice(lineStart, lineEnd))) continue;
    }
    return line;
  }
  return null;
};

const docSuburbHint = text ? readAddress(text) : null;

if (text) {
  // Area, in square metres. The unit is written a dozen ways and every one of them means the
  // same thing: m2, m², sqm, sq m, square metres.
  const AREA = [
    /(\d+(?:\.\d+)?)\s*(?:m2|m²|sqm|sq\.?\s*m|square\s*met(?:re|er)s?)\b/i,
    /(?:area|floor|wall)\D{0,12}?(\d+(?:\.\d+)?)\s*(?:m2|m²|sqm)/i,
  ];
  for (const pattern of AREA) {
    const match = text.match(pattern);
    const value = match ? num(match[1]) : null;
    // Under a square metre is a tile, not a job. Over 500 is a warehouse, not a bathroom.
    if (value !== null && value >= 1 && value <= 500) { facts.floorAreaSqm = value; break; }
  }

  // Tile size, written as the trade writes it: 600x600, 600 x 600mm, 300X600.
  const size = text.match(/(\d{3,4})\s*[x×]\s*(\d{3,4})/i);
  if (size) {
    const a = Number(size[1]);
    const b = Number(size[2]);
    const key = `${a}x${b}`;
    const KNOWN = ['300x300', '600x600', '300x600', '600x300'];
    if (KNOWN.includes(key)) facts.tileSize = key === '600x300' ? '300x600' : key;
    else if (a >= 600 && b >= 1200) facts.tileSize = 'large-format';
  }

  // Room, which is the only thing that decides waterproofing. Never asked as "is this a wet
  // area?" — that is a building-code question and the customer cannot answer it.
  const ROOMS = [
    ['bathroom', /bathroom|ensuite|shower recess|wet area/i],
    ['laundry', /laundry/i],
    ['kitchen', /kitchen|splash ?back/i],
    ['outdoor', /outdoor|alfresco|balcony|patio|verandah/i],
    ['living', /living|lounge|hallway|bedroom|dining/i],
  ];
  const room = ROOMS.find(([, pattern]) => pattern.test(text));
  if (room) facts.room = room[0];

  // Surface. "Floor and wall" is common enough on a real quote to be worth catching first.
  if (/floor\s*(?:and|&|\+)\s*wall|wall\s*(?:and|&|\+)\s*floor/i.test(text)) facts.surface = 'both';
  else if (/\bwall til/i.test(text)) facts.surface = 'wall';
  else if (/\bfloor til/i.test(text)) facts.surface = 'floor';

  // Removal. Only ever set to true — silence is not a statement that there are no old tiles.
  const REMOVAL = /\b(?:remov\w*|demoli\w*|strip\w*|rip\s*(?:up|out)|lift\w*|dispos\w*)\b[^.\n]{0,40}(?:til|floor)/i;
  const NEGATED = /\b(?:no|not|excl\w*|without|nil)\b[^.\n]{0,24}(?:remov|demoli|strip)/i;
  if (REMOVAL.test(text) && !NEGATED.test(text)) facts.removeOldTiles = true;

  // Laying pattern. Herringbone roughly doubles the labour of a straight lay, so a document
  // that names it has said something that changes the price.
  const PATTERNS = [
    ['herringbone', /herringbone|chevron/i],
    ['diagonal', /diagonal|45\s*degree/i],
    ['brick', /brick\s*(?:bond|lay|pattern)|offset|stagger/i],
    ['straight', /straight\s*(?:lay|set)|stack\s*bond/i],
  ];
  const pattern = PATTERNS.find(([, re]) => re.test(text));
  if (pattern) facts.pattern = pattern[0];

  // The headline the customer means when they say what they were quoted: GST-inclusive, so the
  // largest, and never the Subtotal.
  const totals = [...text.matchAll(/(sub[\s-]*)?total\b[^\n$]{0,16}\$\s?([\d,]+(?:\.\d{1,2})?)/gi)]
    .filter((match) => !match[1])
    .map((match) => Number(match[2].replace(/,/g, '')))
    .filter((value) => Number.isFinite(value) && value > 0);
  if (totals.length) facts.existingPrice = Math.max(...totals);
}

// Handed over under the heading the agent's prompt already treats as settled fact. The address
// gets its own heading, worded the way the prompt's suburb rule already describes it, so the
// agent suggests it rather than treating it as an answer.
const docFactsBlock =
  (Object.keys(facts).length
    ? '\n\n--- Already established for this job, do NOT ask about these again ---\n' + JSON.stringify(facts)
    : '') +
  (docSuburbHint
    ? '\n\n--- Job address on the document (this is suggestedSuburb ONLY — checklist.suburb stays null until the customer picks it from the list) ---\n' +
      docSuburbHint
    : '');

// Per-turn note for the agent. Search uses the domain (any AU site). Scrape is still only
// for ALLOWED retailers, handled upstream. If the page already produced a product, skip this.
const extractedOk = Boolean(item.tileFacts && item.tileFacts.tileName);
const domain = item.tileUrlDomain || null;
const tileReadFailedNote = (!extractedOk && domain)
  ? '\n\n--- NOTE: the customer pasted a link to ' + domain +
    '. Always ask tileName first if you do not already have it. Then call tile_price_lookup with query = the tile description AND site = \'' + domain +
    '\' so the search stays on that website. If that search finds nothing, say so in one line and call the tool again without site (Australia-wide). ---'
  : '';

return [{
  json: {
    message: item.message,
    sessionId: item.sessionId,
    place: item.place,
    knownChecklist: item.knownChecklist,
    extractedText: text,
    docFacts: facts,
    docSuburbHint,
    docFactsBlock,
    tileReadFailed: item.tileReadFailed === true,
    tileUrlDomain: item.tileUrlDomain || null,
    tileReadFailedNote,
    unknownUrl: null,
  },
}];

// The deterministic backstop. Same job as the fencing workflow's Format New-Quote Result:
// the model decides what to say, this node decides whether it was allowed to say it.
const source = $('Normalize Extracted Text').first().json;
const sessionId = source.sessionId || null;

// Track whether this session has been seen before, so turn 1's opener message
// is never overwritten by the deterministic "ask next field" fallback below.
const staticData = $getWorkflowStaticData('node');
if (!staticData.seenSessions) staticData.seenSessions = {};
const isFirstTurn = sessionId ? !staticData.seenSessions[sessionId] : true;
if (sessionId) staticData.seenSessions[sessionId] = true;

let place = null;
try { place = JSON.parse(source.place || 'null'); } catch (error) { place = null; }

const parsed = $input.first().json.output || {};

// Order matters: this is the order questions get asked in when the model tries to skip ahead.
const FIELDS = ['suburb', 'surface', 'room', 'floorAreaSqm', 'wallAreaSqm', 'removeOldTiles', 'substrate', 'tileSize', 'pattern', 'tileName'];

// The canonical question + option set per field, identical to the ones the agent's prompt
// hands it. Kept here so this node can ask a field itself when the model tries to skip ahead —
// the choices are fixed, they never needed the LLM.
const ASK = {
  suburb: { message: 'Which suburb is the job in?', options: [] },
  surface: {
    message: 'Are you tiling the floor, the walls, or both?',
    options: [
      { label: 'Floor', value: 'floor' },
      { label: 'Wall', value: 'wall' },
      { label: 'Both', value: 'both' },
    ],
  },
  room: {
    // Never 'is this a wet area?'. That is a building-code question and the customer cannot
    // answer it — but everybody knows which room they are standing in.
    message: 'Which room is it?',
    options: [
      { label: 'Bathroom', value: 'bathroom' },
      { label: 'Kitchen / splashback', value: 'kitchen' },
      { label: 'Laundry', value: 'laundry' },
      { label: 'Living area', value: 'living' },
      { label: 'Outdoor', value: 'outdoor' },
    ],
  },
  floorAreaSqm: {
    message: 'Roughly how big is the floor area?',
    options: [
      { label: 'Up to 10m²', value: 10 },
      { label: '20m²', value: 20 },
      { label: '40m²', value: 40 },
      { label: '60m²', value: 60 },
      { label: 'Other', value: '__other__' },
    ],
  },
  wallAreaSqm: {
    message: 'And roughly how much wall area?',
    options: [
      { label: 'Up to 5m²', value: 5 },
      { label: '10m²', value: 10 },
      { label: '20m²', value: 20 },
      { label: '30m²', value: 30 },
      { label: 'Other', value: '__other__' },
    ],
  },
  removeOldTiles: {
    message: 'Are there old tiles that need removing?',
    options: [
      { label: 'Yes, remove them', value: true },
      { label: 'No, bare surface', value: false },
    ],
  },
  substrate: {
    message: "What's the surface underneath?",
    options: [
      { label: 'Concrete', value: 'concrete' },
      { label: 'Timber floorboards', value: 'timber' },
      { label: 'Over existing tiles', value: 'existing-tiles' },
    ],
  },
  tileSize: {
    message: 'What size tiles are you after?',
    options: [
      { label: '300x300', value: '300x300' },
      { label: '600x600', value: '600x600' },
      { label: '300x600', value: '300x600' },
      { label: 'Large format', value: 'large-format' },
    ],
  },
  pattern: {
    message: 'How would you like them laid?',
    options: [
      { label: 'Straight', value: 'straight' },
      { label: 'Brick / offset', value: 'brick' },
      { label: 'Herringbone', value: 'herringbone' },
      { label: 'Diagonal', value: 'diagonal' },
    ],
  },
  tileName: {
    message: 'What tile are you after? A name or a short description is enough.',
    options: [],
  },
};

// What the client already has on screen. A turn that quietly drops an established value back to
// null is what produces "it asked me the same thing again".
let known = {};
try { known = JSON.parse(source.knownChecklist || '{}') || {}; } catch (error) { known = {}; }

const docFacts = source.docFacts || {};

// The job address off the same document, kept separate from docFacts because it is never an
// answer — only what the picker opens with.
const docSuburbHint = source.docSuburbHint || null;

// Customers name their suburb in the same breath as everything else ("bathroom retile,
// Pakenham VIC 3810, 12 square metres"). The model is asked to echo that into suggestedSuburb
// and usually does — and "usually" is what reaches the customer as an empty picker after they
// already typed the answer. Read here so it does not depend on the model remembering to.
const userMessage = String(source.message || '');
const MESSAGE_PLACE = [
  /\b([A-Z][A-Za-z'’\-]+(?:\s+[A-Z][A-Za-z'’\-]+){0,3},?\s+(?:VIC|NSW|QLD|SA|WA|TAS|NT|ACT)\s*,?\s*\d{4})\b/,
  /\b([A-Z][A-Za-z'’\-]+(?:\s+[A-Z][A-Za-z'’\-]+){0,2},?\s+(?:VIC|NSW|QLD|SA|WA|TAS|NT|ACT))\b/,
  /\b(?:in|at|near|around)\s+([A-Z][A-Za-z'’\-]{2,}(?:\s+[A-Z][A-Za-z'’\-]+){0,2})\b/,
];
const placeFromMessage = (text) => {
  for (const pattern of MESSAGE_PLACE) {
    const match = text.match(pattern);
    if (match && match[1]) return match[1].trim().replace(/\s+/g, ' ');
  }
  // A bare postcode only when the whole reply is one — otherwise a stray 4-digit number (like
  // an area typed alone) could be misread as a postcode.
  const bare = text.trim().match(/^(\d{4})$/);
  return bare ? bare[1] : null;
};

const EXTRA = ['tilePricePerSqm', 'tileRetailer', 'tileSourceUrl', 'existingPrice'];

const merged = { ...(parsed.checklist || {}) };
// The customer's own answers first.
for (const field of [...FIELDS, ...EXTRA]) {
  if ((merged[field] === null || merged[field] === undefined) && known[field] !== null && known[field] !== undefined) {
    merged[field] = known[field];
  }
}
// Then the document and the read link, for anything still empty.
for (const field of [...FIELDS, ...EXTRA]) {
  if ((merged[field] === null || merged[field] === undefined) && docFacts[field] !== null && docFacts[field] !== undefined) {
    merged[field] = docFacts[field];
  }
}

// A value mined from a quote document arrives written the way the document wrote it: "25m2",
// "$4,180.00". A string reaches the pricing step as NaN and prices nothing at all, with no
// error anywhere to explain why.
const toNumber = (value) => {
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  if (value === null || value === undefined) return null;
  const text = String(value).replace(/,(?=\d{3}\b)/g, '');
  const match = text.match(/-?\d+(?:\.\d+)?/);
  if (!match) return null;
  const parsed = Number(match[0]);
  return Number.isFinite(parsed) ? parsed : null;
};

for (const field of ['floorAreaSqm', 'wallAreaSqm', 'tilePricePerSqm', 'existingPrice']) {
  if (merged[field] !== null && merged[field] !== undefined) merged[field] = toNumber(merged[field]);
}

// Snap free text back onto the slugs the pricing document is keyed by. A value that means the
// right thing but is spelled differently matches nobody, silently.
const snap = (value, allowed, hints) => {
  if (typeof value !== 'string' || !value.trim()) return value;
  const lower = value.trim().toLowerCase();
  const exact = allowed.find((option) => option.toLowerCase() === lower);
  if (exact) return exact;
  const hint = hints.find(([, pattern]) => pattern.test(value));
  // No hint matches: leave the words alone rather than guessing. The pricing step will find
  // nobody and say so, which is better than pricing the wrong job.
  return hint ? hint[0] : value;
};

merged.surface = snap(merged.surface, ['floor', 'wall', 'both'], [
  ['both', /both|floor.*wall|wall.*floor/i],
  ['wall', /wall|splash/i],
  ['floor', /floor|ground/i],
]);
merged.room = snap(merged.room, ['bathroom', 'kitchen', 'laundry', 'living', 'outdoor'], [
  ['bathroom', /bath|ensuite|shower|toilet|powder/i],
  ['laundry', /laundry|utility/i],
  ['kitchen', /kitchen|splash/i],
  ['outdoor', /outdoor|alfresco|balcony|patio|verandah|deck/i],
  ['living', /living|lounge|hall|bedroom|dining|entry/i],
]);
merged.substrate = snap(merged.substrate, ['concrete', 'timber', 'existing-tiles'], [
  ['existing-tiles', /existing|over til|old til/i],
  ['timber', /timber|wood|floorboard|ply/i],
  ['concrete', /concrete|slab|screed/i],
]);
merged.tileSize = snap(merged.tileSize, ['300x300', '600x600', '300x600', 'large-format'], [
  ['large-format', /large|1200|900x|slab/i],
  ['300x600', /300\s*[x×]\s*600|600\s*[x×]\s*300/i],
  ['600x600', /600\s*[x×]\s*600/i],
  ['300x300', /300\s*[x×]\s*300/i],
]);
merged.pattern = snap(merged.pattern, ['straight', 'brick', 'herringbone', 'diagonal'], [
  ['herringbone', /herringbone|chevron/i],
  ['diagonal', /diagonal|45/i],
  ['brick', /brick|offset|stagger|running bond/i],
  ['straight', /straight|stack|grid/i],
]);

// Areas are square metres. A customer who types 270 meaning square feet, or 0.5 meaning half a
// room, has not given an area anybody can price — so implausible values are dropped rather than
// carried into a total.
for (const field of ['floorAreaSqm', 'wallAreaSqm']) {
  const value = merged[field];
  if (value !== null && value !== undefined && (!Number.isFinite(value) || value < 1 || value > 500)) {
    merged[field] = null;
  }
}

// Picker confirmation is the suburb. Do not wait for the model to copy it.
if (place && (merged.suburb === null || merged.suburb === undefined || merged.suburb === '')) {
  merged.suburb = place.displayLabel || [place.suburb, place.state, place.postcode].filter(Boolean).join(', ') || merged.suburb;
}

// What to open the picker with, newest signal first: what they just typed, then the attached
// document, then whatever the model managed to suggest, then a name it wrote into the checklist
// without a picker behind it. None of these is an answer — the customer still taps the Google
// suggestion to confirm.
const suburbHint =
  placeFromMessage(userMessage) ||
  docSuburbHint ||
  (typeof parsed.suggestedSuburb === 'string' && parsed.suggestedSuburb.trim() ? parsed.suggestedSuburb.trim() : null) ||
  (typeof merged.suburb === 'string' && merged.suburb.trim() ? merged.suburb.trim() : null) ||
  null;

const checklist = Object.keys(merged).length > 0 ? merged : null;

// Two fields are conditional, for the same reason siteAccess is conditional in fencing: a
// question that cannot have a useful answer should not be asked.
const isMissing = (field) => {
  if (!checklist) return true;
  // A suburb nobody confirmed against Google is not established, whoever wrote it down. Without
  // a place there are no coordinates, and matching runs on distance — so a name on its own can
  // never produce a quote. Treating it as missing is what puts the picker on screen.
  if (field === 'suburb' && !place) return true;
  if (field === 'floorAreaSqm' && checklist.surface === 'wall') return false;
  if (field === 'wallAreaSqm' && checklist.surface === 'floor') return false;
  // With the old tiles coming up, the customer does not know what is underneath. Asking gets a
  // guess, and a guess here changes the price.
  if (field === 'substrate' && checklist.removeOldTiles === true) return false;
  if (field === 'tileName') {
    const name = checklist.tileName;
    return name === null || name === undefined || String(name).trim() === '';
  }
  return checklist[field] === null || checklist[field] === undefined;
};

const missing = FIELDS.filter(isMissing);
const nextField = missing[0];

let type = ['question', 'confirmation'].includes(parsed.type) ? parsed.type : 'message';
let message = typeof parsed.message === 'string' ? parsed.message.trim() : '';
let options = Array.isArray(parsed.options) ? parsed.options : [];

// Nothing downstream can recover from an empty bubble, so never emit one.
if (!message) {
  message = nextField ? ASK[nextField].message : "Sorry, something went wrong on my end — mind trying that again in a moment?";
  if (nextField) {
    type = ASK[nextField].options.length ? 'question' : 'message';
    options = ASK[nextField].options;
  } else {
    type = 'message';
    options = [];
  }
}

// The agent thinks it already has the suburb — it read the name off a message or a document —
// so it will never ask again of its own accord, and only asking puts the picker in front of the
// customer. Nothing else in the system can turn a name into a place.
if (checklist && checklist.suburb && !place) {
  type = 'message';
  message = ASK.suburb.message;
  options = [];
}

// Recapping after several answers and then carrying on with fields it never asked about is the
// model's favourite mistake — sometimes as a "confirmation" it isn't entitled to, sometimes just
// by narrating a handoff-shaped message while a field is still null. Any type is corrected here,
// not just "confirmation": a missing field always wins over whatever the model tried to say.
if (missing.length > 0 && !isFirstTurn) {
  // When the agent is showing tile_price_lookup results, keep those options instead of
  // replacing them with the blank "what tile?" prompt.
  const keepTileOptions = nextField === 'tileName'
    && Array.isArray(parsed.options)
    && parsed.options.length > 0;
  if (!keepTileOptions) {
    type = ASK[nextField].options.length ? 'question' : 'message';
    message = ASK[nextField].message;
    options = ASK[nextField].options;
    // Asking blank when the address is sitting on the page (or in the message) they just sent is
    // the version of this that reads as not having looked. Same one-tap confirmation either way —
    // the wording just says what was found, and the word 'suburb' stays in it so the picker opens.
    if (nextField === 'suburb' && suburbHint) {
      message = 'I found ' + suburbHint + ' — confirm that suburb from the list?';
    }
  }
}

const priceMissing = !checklist
  || checklist.tilePricePerSqm === null
  || checklist.tilePricePerSqm === undefined
  || checklist.tilePricePerSqm === '';

// Name without a looked-up price must not reach confirmation.
if (missing.length === 0 && priceMissing && !isFirstTurn) {
  if (parsed.type === 'confirmation' || parsed.checklistComplete) {
    if (Array.isArray(parsed.options) && parsed.options.length > 0) {
      type = 'question';
      message = message || 'Found a few that match — which one?';
      options = parsed.options;
    } else {
      type = 'message';
      message = ASK.tileName.message;
      options = [];
    }
  }
}

// Which field the client should collect with something other than a plain text box. Only the
// suburb qualifies: a mistyped suburb doesn't fail loudly, it silently matches zero tilers, so
// the client swaps its reply box for a Google-backed suburb picker and sends back a real place.
// Derived from the checklist, never from the model — 'suburb' is first in FIELDS, so it is the
// field due whenever it is still missing.
const asksForSuburb = /\bsuburbs?\b|\bpost ?code\b/i.test(message);
const expectsSuburb = nextField === 'suburb' && options.length === 0 && asksForSuburb;

return [{
  json: {
    sessionId,
    trade: 'tiling',
    intent: checklist && checklist.existingPrice !== null && checklist.existingPrice !== undefined ? 'compare_quote' : 'new_quote',
    place,
    type,
    message,
    options,
    ...(expectsSuburb ? { expects: 'suburb' } : {}),
    // What the customer or their document called the place. Not an answer — a head start for
    // the picker, which still makes them confirm it against Google.
    ...(expectsSuburb && suburbHint ? { suggestedSuburb: suburbHint } : {}),
    checklistComplete: missing.length === 0 && !priceMissing && !!parsed.checklistComplete,
    checklist,
    results: [],
    avgRatePerSqm: null,
  },
}];

// Every tiler that covers the customer, priced off its own published rates, ranked cheapest
// first. Labour only — the tiles are the customer's to buy, and they are reported separately as
// an estimate so nobody is on the hook for a retailer's price changing.
const gate = $('Format Tiling Result').first().json;
const checklist = gate.checklist || {};
const sessionId = gate.sessionId || null;
const intent = gate.intent;
const matcher = $input.first().json || {};

const fail = (message, reason) => [{
  json: { sessionId, trade: 'tiling', intent, type: 'result', message, options: [], results: [],
    avgRatePerSqm: null, comparison: null, materials: null, noMatchReason: reason,
    checklist, checklistComplete: true },
}];

// n8n does not always throw when a sub-workflow fails — an empty item comes back instead. Left
// unchecked that reads to the customer as "nobody covers you", which is a different and much
// more damaging statement than "something broke".
if (matcher.matched === undefined) {
  return fail("Something went wrong finding tilers near you — mind trying again in a moment?", 'error');
}

if (matcher.matched !== true) {
  const reason = matcher.noMatchReason || 'area';
  const message = reason === 'place'
    ? "I couldn't place that suburb on the map. Could you pick it from the suggestions?"
    : reason === 'radius'
      ? 'There are tilers in that suburb, but none of them travel far enough to reach you.'
      : 'No tiler has registered that suburb yet. Try a nearby suburb?';
  return fail(message, reason);
}

const slug = (value) =>
  String(value == null ? '' : value).toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

const num = (value) => {
  const raw = value !== null && typeof value === 'object'
    ? (value.doubleValue ?? value.integerValue ?? value.stringValue ?? null)
    : value;
  const parsed = Number(raw);
  return Number.isFinite(parsed) ? parsed : null;
};

// Every figure the customer sees is what they would actually pay. Some businesses publish
// GST-inclusive rates and some do not, and the customer's own quote almost always includes it —
// so an exclusive rate looks 10% cheaper than it is.
const GST_MULTIPLIER = 1.1;
const payable = (amount, gstInclusive) => (gstInclusive ? amount : Math.round(amount * GST_MULTIPLIER));

const surface = checklist.surface;
const floorArea = surface === 'wall' ? 0 : (num(checklist.floorAreaSqm) || 0);
const wallArea = surface === 'floor' ? 0 : (num(checklist.wallAreaSqm) || 0);
const totalArea = floorArea + wallArea;

// Waterproofing is decided by the room, never by asking the customer. Bathrooms and laundries
// are wet areas under AS 3740 whether or not anybody mentions it.
const WET_ROOMS = ['bathroom', 'laundry'];
const wetArea = WET_ROOMS.includes(checklist.room);

const tileSize = checklist.tileSize;
const pattern = checklist.pattern;
const substrate = checklist.substrate;

const quotes = [];
let blockedBySurface = 0;
let blockedBySize = 0;
let blockedByMinimum = 0;

const businesses = Array.isArray(matcher.businesses) ? matcher.businesses : [];
const pricingDocs = Array.isArray(matcher.pricing) ? matcher.pricing : [];

for (let index = 0; index < businesses.length; index += 1) {
  const business = businesses[index] || {};
  const pricing = pricingDocs[index] || {};
  if (!business.uid || pricing.isComplete !== true) continue;

  const enabled = Array.isArray(pricing.enabledSurfaces) ? pricing.enabledSurfaces.map(slug) : [];
  const needsFloor = floorArea > 0;
  const needsWall = wallArea > 0;
  if ((needsFloor && !enabled.includes('floor')) || (needsWall && !enabled.includes('wall'))) {
    blockedBySurface += 1;
    continue;
  }

  // Most tilers will not travel for a job below a few square metres. That is a real constraint,
  // not a rounding rule — showing them a job they would decline wastes everybody's time.
  const minimumJobSqm = num(pricing.minimumJobSqm) || 0;
  if (totalArea < minimumJobSqm) { blockedByMinimum += 1; continue; }

  const rates = pricing.rates || {};
  const rateFor = (surfaceKey) => {
    const table = rates[surfaceKey] || {};
    const key = Object.keys(table).find((candidate) => slug(candidate) === slug(tileSize));
    return key ? num(table[key]) : null;
  };

  const floorRate = needsFloor ? rateFor('floor') : 0;
  const wallRate = needsWall ? rateFor('wall') : 0;
  // A business that publishes no rate at this tile size cannot quote it. Borrowing a rate from a
  // neighbouring size would not be their price.
  if ((needsFloor && floorRate === null) || (needsWall && wallRate === null)) { blockedBySize += 1; continue; }

  const patternAdd = num((pricing.patternSurcharge || {})[pattern]) || 0;
  const substrateAdd = substrate ? (num((pricing.substrateSurcharge || {})[substrate]) || 0) : 0;

  const floorCost = floorArea * ((floorRate || 0) + patternAdd + substrateAdd);
  const wallCost = wallArea * ((wallRate || 0) + patternAdd + substrateAdd);

  const waterproofing = pricing.waterproofing || {};
  const waterproofCost = wetArea && waterproofing.offered === true
    ? (num(waterproofing.perSqm) || 0) * totalArea
    : 0;

  const removal = pricing.removal || {};
  const removalCost = checklist.removeOldTiles === true && removal.offered === true
    ? (num(removal.perSqm) || 0) * totalArea
    : 0;

  const gstInclusive = pricing.gstInclusive === true;
  const subtotal = Math.round(floorCost + wallCost + waterproofCost + removalCost);
  const minimumCharge = payable(num(pricing.minimumCharge) || 0, gstInclusive);
  const total = Math.max(payable(subtotal, gstInclusive), minimumCharge);

  // The headline rate the card shows. Blended across floor and wall when both are being done,
  // because one number is what the customer compares.
  const blendedRate = totalArea > 0 ? Math.round(payable(subtotal, gstInclusive) / totalArea) : 0;

  const badges = [];
  badges.push(gstInclusive ? 'incl. GST' : 'incl. GST (added)');
  badges.push(business.distanceKm > 0 ? business.distanceKm + ' km away' : 'In your suburb');
  if (business.rating) badges.push(business.reviewCount ? business.rating + '★ (' + business.reviewCount + ')' : business.rating + '★');
  if (waterproofCost > 0) badges.push('Waterproofing included');
  if (removalCost > 0) badges.push('Removal included');
  if (business.isAutoAcceptEnabled) badges.push('Instant accept');

  quotes.push({
    uid: business.uid,
    businessName: business.businessName,
    suburb: business.suburb,
    distanceKm: business.distanceKm,
    ratePerSqm: blendedRate,
    autoAcceptsAi: business.autoAcceptsAi === true,
    currency: pricing.currency || 'AUD',
    projectTotalMin: total,
    projectTotalMax: total,
    estimatedTotal: total,
    badges,
  });
}

quotes.sort((a, b) => a.projectTotalMin - b.projectTotalMin || b.ratePerSqm - a.ratePerSqm);

const existingPrice = num(checklist.existingPrice);
// What tilers round here charge for this job — every one that could quote it, not just the
// handful shown. Averaging only the cheapest three would flatter the saving.
const average = quotes.length > 0 ? Math.round(quotes.reduce((sum, quote) => sum + quote.projectTotalMin, 0) / quotes.length) : null;

const beating = existingPrice === null ? quotes : quotes.filter((quote) => quote.projectTotalMin < existingPrice);
const top = beating.slice(0, 3);

if (top.length === 0 && existingPrice !== null && quotes.length > 0) {
  const closest = quotes[0].projectTotalMin;
  return fail('Nobody covering your suburb came in under $' + existingPrice.toLocaleString() +
    '. The closest was $' + closest.toLocaleString() + ', so the quote you have is already a good one.', 'notCheaper');
}

if (top.length === 0) {
  // Say which wall they hit. A tile size nobody prices is a different problem from a job too
  // small to take, and only one of them is worth changing the answer for.
  const reason = blockedBySurface > 0 ? 'surface' : blockedBySize > 0 ? 'tileSize' : blockedByMinimum > 0 ? 'minimum' : 'pricing';
  const message = reason === 'surface'
    ? 'The tilers near you do not cover that kind of work yet. Want to try a different suburb?'
    : reason === 'tileSize'
      ? 'Nobody near you publishes a rate for that tile size. Want to try a different size?'
      : reason === 'minimum'
        ? 'That job is smaller than the tilers near you will travel for. Most have a minimum of around 5m².'
        : 'I found tilers near you, but none of them have finished setting up their pricing yet.';
  return fail(message, reason);
}

// The tiles. Never part of a business's total — the customer buys these, so this is a budgeting
// figure and it is labelled as one, with the source and the date it was read.
const WASTAGE = ['herringbone', 'diagonal'].includes(pattern) ? 1.15 : 1.10;
const areaWithWastage = Math.round(totalArea * WASTAGE * 10) / 10;

// Typical Australian retail, used only when the customer has not chosen a tile yet. A range, not
// a number, because that is honestly all it is.
const CATEGORY_ESTIMATE = { '300x300': [28, 45], '600x600': [35, 60], '300x600': [32, 55], 'large-format': [55, 95] };

const tilePrice = num(checklist.tilePricePerSqm);
let materials = null;
if (tilePrice !== null && checklist.tileName) {
  materials = {
    tileName: checklist.tileName,
    retailer: checklist.tileRetailer || null,
    pricePerSqm: tilePrice,
    areaWithWastage,
    wastagePercent: Math.round((WASTAGE - 1) * 100),
    total: Math.round(tilePrice * areaWithWastage),
    sourceUrl: checklist.tileSourceUrl || null,
    fetchedAt: Date.now(),
    confidence: 'extracted',
  };
} else {
  const band = CATEGORY_ESTIMATE[tileSize] || [30, 60];
  materials = {
    tileName: null,
    retailer: null,
    pricePerSqm: null,
    priceRangePerSqm: band,
    areaWithWastage,
    wastagePercent: Math.round((WASTAGE - 1) * 100),
    totalRange: [Math.round(band[0] * areaWithWastage), Math.round(band[1] * areaWithWastage)],
    sourceUrl: null,
    fetchedAt: null,
    confidence: 'estimated',
  };
}

const benchmark = existingPrice === null ? average : existingPrice;
const cheapest = top[0].projectTotalMin;

return [{
  json: {
    sessionId,
    trade: 'tiling',
    intent,
    type: 'result',
    message: 'Here are the local tilers that cover your job.',
    options: [],
    results: top.map((quote) => ({
      businessId: quote.uid,
      autoAcceptsAi: quote.autoAcceptsAi,
      businessName: quote.businessName,
      suburb: quote.suburb,
      ratePerSqm: quote.ratePerSqm,
      estimatedTotal: quote.estimatedTotal,
      notes: quote.badges.join(' · '),
    })),
    avgRatePerSqm: Math.round(top.reduce((sum, quote) => sum + quote.ratePerSqm, 0) / top.length),
    comparison: {
      potentialSavings: benchmark > cheapest ? benchmark - cheapest : null,
      marketAverage: average,
      totalQuotesScreened: matcher.totalCovering || businesses.length,
      userExistingPrice: existingPrice,
      quotes: top.map((quote) => ({
        businessId: quote.uid,
        autoAcceptsAi: quote.autoAcceptsAi,
        businessName: quote.businessName,
        ratePerSqm: quote.ratePerSqm,
        projectTotalMin: quote.projectTotalMin,
        projectTotalMax: quote.projectTotalMax,
        badges: quote.badges,
        tag: quote.projectTotalMin === cheapest ? 'BEST_VALUE' : null,
        savingsFromAverage: benchmark > quote.projectTotalMin ? benchmark - quote.projectTotalMin : null,
        suburb: quote.suburb,
      })),
    },
    // Absent on fencing, present here. An older client that does not know this key ignores it.
    materials,
    checklist,
    checklistComplete: true,
  },
}];
